begin;
\ir ../fixtures.sql
select no_plan();
select is((select count(*) from public.services), 3::bigint, 'Only three real initial one-off services seeded');
select is((select count(*) from public.services where price_minor is not null or duration_minutes is not null), 0::bigint, 'No invented prices or durations');
select is((select count(*) from public.service_areas), 0::bigint, 'No fictional coverage seeded');
select throws_ok($$insert into public.services(category_id,name,slug) values('90000000-0000-4000-8000-000000000001','Fixture','fixture')$$, '23503', null, 'Category FK required');
select throws_ok($$update public.services set price_minor = -1 where slug = 'personal-yoga'$$, '23514', null, 'Negative prices rejected');
select throws_ok($$update public.services set duration_minutes = 0 where slug = 'personal-yoga'$$, '23514', null, 'Invalid duration rejected');
select throws_ok($$update public.services set currency = 'USD' where slug = 'personal-yoga'$$, '23514', null, 'Only INR supported');
select throws_ok($$update public.services set is_active = false where slug = 'personal-yoga'$$, '23514', null, 'Inactive service cannot remain published');
select throws_ok($$update public.services set name = null where slug = 'personal-yoga'$$, '23502', null, 'Required name enforced');
select throws_ok($$update public.services set slug = 'personal-yoga' where slug = 'naturopathy'$$, '23505', null, 'Stable slugs unique');
select throws_ok($$delete from public.service_categories where slug = 'yoga'$$, '23503', null, 'Used category deletion restricted');
update public.services set is_published = false where slug = 'naturopathy';

set local role anon;
select is((select count(*) from public.services), 2::bigint, 'Anon sees only published services');
select is((select count(*) from public.services where slug = 'naturopathy'), 0::bigint, 'Unpublished service confidential');
select throws_ok($$update public.services set price_minor = 1$$, '42501', null, 'Anon cannot modify prices');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub', '10000000-0000-4000-8000-000000000003', true);
select lives_ok($$update public.services set price_minor = 1 where slug = 'personal-yoga'$$, 'RLS-denied customer update affects no rows');
reset role;
select is((select price_minor from public.services where slug = 'personal-yoga'), null::bigint, 'Customer price update did not succeed');
set local role authenticated;
select set_config('request.jwt.claim.sub', '10000000-0000-4000-8000-000000000005', true);
select throws_ok($$insert into public.professional_services(professional_id,service_id,approved_by) select auth.uid(),id,auth.uid() from public.services where slug = 'personal-yoga'$$, '42501', null, 'Professional cannot self-approve service');
select throws_ok($$insert into public.service_areas(name,is_active) values('Test-only area',true)$$, '42501', null, 'Professional cannot invent approved geographic coverage');
select set_config('request.jwt.claim.sub', '10000000-0000-4000-8000-000000000001', true);
select lives_ok($$update public.services set is_published = true where slug = 'naturopathy'$$, 'Admin publication succeeds');
select lives_ok($$insert into public.professional_services(professional_id,service_id,approved_by) select '10000000-0000-4000-8000-000000000005',id,auth.uid() from public.services where slug = 'personal-yoga'$$, 'Admin approves service eligibility');
select throws_ok($$insert into public.professional_services(professional_id,service_id,approved_by) select '10000000-0000-4000-8000-000000000005',id,auth.uid() from public.services where slug = 'personal-yoga'$$, '23505', null, 'Duplicate eligibility rejected');
select lives_ok($$insert into public.service_areas(name,postal_code,is_active) values('Disposable test coverage','110001',false)$$, 'Admin may define test coverage');
select throws_ok($$insert into public.service_areas(name,postal_code) values('Invalid fixture','000000')$$, '23514', null, 'Invalid postal code rejected');
select lives_ok($$insert into public.professional_service_areas(professional_id,service_area_id,approved_by) select '10000000-0000-4000-8000-000000000005',id,auth.uid() from public.service_areas where name = 'Disposable test coverage'$$, 'Admin approves service-area eligibility');
select set_config('request.jwt.claim.sub', '10000000-0000-4000-8000-000000000005', true);
select is((select count(*) from public.professional_services), 1::bigint, 'Professional can read own approved assignments');
select throws_ok($$insert into public.professional_service_areas(professional_id,service_area_id,approved_by) values(auth.uid(),'90000000-0000-4000-8000-000000000001',auth.uid())$$, '42501', null, 'Professional cannot self-approve coverage');
reset role;
update public.service_categories set is_active = false where slug = 'yoga';
set local role anon;
select is((select count(*) from public.services where slug = 'personal-yoga'), 0::bigint, 'Inactive category hides published service');
reset role;
delete from auth.users where id = '10000000-0000-4000-8000-000000000005';
select is((select count(*) from public.professional_services), 0::bigint, 'Professional deletion cascades assignments');
select is((select count(*) from public.professional_service_areas), 0::bigint, 'Professional deletion cascades coverage');
select ok(exists(select 1 from public.administrative_audit where target_user_id = '10000000-0000-4000-8000-000000000005'), 'Deletion retains immutable audit identity');
select * from finish();
rollback;
